-- 14) 스마트 공항 공고(R26BK8000303) 를 제안 작성 중으로 내린다
--     가짜 번호라 제출 완료로 두면 [지금 수집] 의 결과 등록 단계가 헛돌고 수집 로그에 실패가 남는다.
--     제출 완료 공고는 시연 사업 하나만 남는다. 마감·개찰·발표일은 앞으로 민다.
UPDATE TB_BID_PBANC SET PBANC_STTS_CD = 'PS040', SBMSN_DT = NULL, PRSNR_ID = NULL,
    BID_DDLN_DT = TRUNC(SYSDATE) + 6 + 10.0/24, OPENG_DT = TRUNC(SYSDATE) + 8 + 11.0/24,
    PRSNTN_DT = TRUNC(SYSDATE) + 10 + 14.0/24
  WHERE BID_PBANC_NO = 'R26BK8000303';
DELETE FROM TB_PBANC_PRCS_HSTRY
  WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK8000303')
    AND PRCS_SE_CD = 'PC090';
UPDATE TB_SBMSN_DCMNT SET SBMSN_DDLN_DT = TRUNC(SYSDATE) + 5 + 10.0/24
  WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK8000303');

