UPDATE TB_CO_EVL_RSLT SET CO_NM = '엑사아이엔티' WHERE CO_NM = '오티아이';

COMMIT;

-- 16) 확인: 아래가 모두 기대값이어야 한다
-- 한 번에 보도록 UNION ALL 로 묶는다. 판정이 모두 OK 여야 한다.
SELECT '시연 사업 입찰공고·제출완료·결과없음' AS 확인, TO_CHAR(v) || ' / 1' AS 값, CASE WHEN v = 1 THEN 'OK' ELSE '<<< 확인' END AS 판정, 1 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_BID_PBANC p WHERE p.BID_PBANC_NO = 'R26BK01541118' AND p.PBANC_STEP_CD = 'PP030' AND p.PBANC_STTS_CD = 'PS050' AND NOT EXISTS (SELECT 1 FROM TB_BID_RSLT r WHERE r.PBANC_SN = p.PBANC_SN) AND NOT EXISTS (SELECT 1 FROM TB_CO_EVL_RSLT c WHERE c.PBANC_SN = p.PBANC_SN)) AS v FROM DUAL)
 UNION ALL
SELECT '제출 완료 상태인 공고 수' AS 확인, TO_CHAR(v) || ' / 1' AS 값, CASE WHEN v = 1 THEN 'OK' ELSE '<<< 확인' END AS 판정, 2 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_BID_PBANC WHERE PBANC_STTS_CD = 'PS050') AS v FROM DUAL)
 UNION ALL
SELECT '시연 사업 목차 수 (제안서35+요약서4)' AS 확인, TO_CHAR(v) || ' / 39' AS 값, CASE WHEN v = 39 THEN 'OK' ELSE '<<< 확인' END AS 판정, 3 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_TOC WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118')) AS v FROM DUAL)
 UNION ALL
SELECT '시연 사업 요구사항 수' AS 확인, TO_CHAR(v) || ' / 111' AS 값, CASE WHEN v = 111 THEN 'OK' ELSE '<<< 확인' END AS 판정, 4 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118')) AS v FROM DUAL)
 UNION ALL
SELECT '목차에 안 붙은 요구사항' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 5 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_RQT_MTTR WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118') AND TOC_SN IS NULL) AS v FROM DUAL)
 UNION ALL
SELECT '최하위 아닌 목차에 붙은 요구사항' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 6 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_RQT_MTTR r WHERE r.PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118') AND EXISTS (SELECT 1 FROM TB_TOC c WHERE c.UP_TOC_SN = r.TOC_SN)) AS v FROM DUAL)
 UNION ALL
SELECT '최하위 아닌 목차에 붙은 파일' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 7 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_ATCH_FILE f WHERE f.PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118') AND f.TOC_SN IS NOT NULL AND EXISTS (SELECT 1 FROM TB_TOC c WHERE c.UP_TOC_SN = f.TOC_SN)) AS v FROM DUAL)
 UNION ALL
SELECT '예상 쪽수 합계 (쪽수 제한과 같아야)' AS 확인, TO_CHAR(v) || ' / 200' AS 값, CASE WHEN v = 200 THEN 'OK' ELSE '<<< 확인' END AS 판정, 8 AS s FROM (SELECT (SELECT NVL(SUM(EXPC_PAGE_CNT), 0) FROM TB_TOC WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118') AND TOC_SE_CD = 'TC010') AS v FROM DUAL)
 UNION ALL
SELECT '조견표 배점 합계' AS 확인, TO_CHAR(v) || ' / 90' AS 값, CASE WHEN v = 90 THEN 'OK' ELSE '<<< 확인' END AS 판정, 9 AS s FROM (SELECT (SELECT NVL(SUM(EVL_SCOR_SCR), 0) FROM TB_EVL_ARTCL WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118')) AS v FROM DUAL)
 UNION ALL
SELECT '시연 사업 파일 수' AS 확인, TO_CHAR(v) || ' / 45' AS 값, CASE WHEN v = 45 THEN 'OK' ELSE '<<< 확인' END AS 판정, 10 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_ATCH_FILE WHERE PBANC_SN = (SELECT PBANC_SN FROM TB_BID_PBANC WHERE BID_PBANC_NO = 'R26BK01541118')) AS v FROM DUAL)
 UNION ALL
SELECT '이름을 못 바꾼 계정' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 11 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_USER WHERE USER_NM IN ('박서연', '최민정', '김가희')) AS v FROM DUAL)
 UNION ALL
SELECT '주관팀 팀장이 제안팀원 아닌 시연 사업' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 12 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_BID_PBANC p WHERE p.BID_PBANC_NO = 'R26BK01541118' AND NOT EXISTS (SELECT 1 FROM TB_PRP_TMMBR m JOIN TB_USER u ON u.USER_ID = m.USER_ID WHERE m.PBANC_SN = p.PBANC_SN AND u.TEAM_SN = p.SPRVSN_TEAM_SN AND u.JBGD_CD = 'JG020')) AS v FROM DUAL)
 UNION ALL
SELECT '마감 지났는데 참여확정·작성중인 사업' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 13 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_BID_PBANC WHERE PBANC_STTS_CD IN ('PS030', 'PS040') AND BID_DDLN_DT IS NOT NULL AND BID_DDLN_DT < SYSDATE) AS v FROM DUAL)
 UNION ALL
SELECT '아직 오티아이로 남은 업체평가 행' AS 확인, TO_CHAR(v) || ' / 0' AS 값, CASE WHEN v = 0 THEN 'OK' ELSE '<<< 확인' END AS 판정, 14 AS s FROM (SELECT (SELECT COUNT(*) FROM TB_CO_EVL_RSLT WHERE CO_NM = '오티아이') AS v FROM DUAL)
 ORDER BY s;
